#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    errno = 0;
    long long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || errno != 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (n == 1) {
        puts("NONE");
        return 0;
    }
    long long original = n;
    int first = 1;
    for (long long d = 2; d * d <= n; ++d) {
        int cnt = 0;
        while (n % d == 0) {
            n /= d;
            ++cnt;
        }
        if (cnt) {
            if (!first) putchar(' ');
            printf("%lld^%d", d, cnt);
            first = 0;
        }
    }
    if (n > 1) {
        if (!first) putchar(' ');
        printf("%lld^1", n);
        first = 0;
    }
    putchar('\n');
    return 0;
}
}
